import {FIGURES} from './figures.js';
import {NEURON_QUESTIONS} from './quiz-neurons.js';
import {ANATOMY_QUESTIONS} from './anatomy-data.js';
import {SYNAPSE_QUESTIONS} from './quiz-synapses.js';
const q=(id,scope,chapter,prompt,correct,wrong,explanation)=>({id,scope,chapter,kind:'concepts',prompt,correct,options:[correct,...wrong],explanation});
export const CONCEPT_QUESTIONS=[
q('m2','c1','c1-mouvement','Chez l’humain, quelles régions participent aux aires motrices secondaires ?','Prémoteur latéral et SMA',['Seulement M1','Uniquement le cervelet','A1 et A2'],'Le prémoteur latéral et la SMA participent à la préparation et à l’organisation. M2 est une notation variable selon le cours et l’espèce.'),
q('m1','c1','c1-mouvement','Quel est le principal repère anatomique de M1 ?','Gyrus précentral',['Gyrus postcentral','Sillon calcarin','Hippocampe'],'M1 est surtout dans le gyrus précentral, devant le sillon central.'),
q('sma','c1','c1-mouvement','Où se situe la SMA ?','Face médiale du lobe frontal',['Face latérale occipitale','Dans la cochlée','Sous le thalamus'],'La SMA occupe une partie de la région frontale supérieure médiale ; tout le gyrus frontal supérieur ne correspond pas à la SMA.'),
q('s1','c1','c1-sentir','Le cortex S1 gauche traite principalement la sensibilité de quel côté du corps ?','Du côté droit',['Du côté gauche','Uniquement des deux yeux','Uniquement de l’oreille gauche'],'L’organisation des voies somatosensorielles est principalement controlatérale.'),
q('olfaction','c1','c1-sentir','Quelle voie atteint son cortex primaire sans relais thalamique obligatoire préalable ?','L’olfaction',['La vision','L’audition','La somesthésie'],'Le bulbe projette vers le cortex olfactif primaire. Le thalamus participe néanmoins à des traitements olfactifs ultérieurs.'),
q('v1','c1','c1-voir-entendre','Quel repère aide à localiser V1 ?','Sillon calcarin',['Sillon central','Gyrus de Heschl','Pont'],'V1 se situe principalement autour du sillon calcarin sur la face médiale occipitale.'),
q('a1','c1','c1-voir-entendre','Quel repère aide à localiser A1 ?','Gyri transverses de Heschl',['Gyrus postcentral','Gyrus frontal inférieur','Corps calleux'],'A1 est sur la face supérieure temporale, en partie cachée dans le sillon latéral.'),
q('a2','c1','c1-voir-entendre','Que signifie « A2 » dans ce cours ?','Des traitements auditifs secondaires',['Un noyau moteur du cervelet','Une seule zone identique dans tous les atlas','Le nerf optique'],'A2 est une étiquette pédagogique. Les traitements secondaires impliquent plusieurs champs autour et au-delà d’A1.'),
q('fmri','c1','c1-observer','Que mesure directement le signal BOLD de l’IRMf ?','Des variations liées à l’oxygénation sanguine',['Chaque potentiel d’action','La pensée exacte d’une personne','Le nombre total de synapses'],'L’IRMf renseigne indirectement sur l’activité par un signal hémodynamique.'),
q('tractography','c1','c1-observer','Une fibre reconstruite en tractographie est…','Une estimation de trajet',['La photographie d’un axone individuel','Une mesure directe d’un souvenir','Une synapse agrandie'],'L’IRM de diffusion fournit des indices permettant d’estimer des connexions, avec des limites de reconstruction.'),
q('grey','c1','c1-tissus','La substance grise se trouve…','Dans le cortex et dans des noyaux profonds',['Seulement à la surface du cerveau','Uniquement dans le corps calleux','Uniquement dans les nerfs périphériques'],'Le thalamus et d’autres noyaux profonds contiennent aussi de la substance grise.'),
q('sulcus','c1','c1-reperes','Quelle distinction est correcte ?','Gyrus = relief ; sillon = creux',['Gyrus = creux ; sillon = relief','Gyrus = nerf ; sillon = noyau','Ce sont deux noms du même relief'],'Les gyri sont les replis en relief et les sillons les creux qui les séparent.'),
q('insula','c1','c1-reperes','Où est l’insula ?','Au fond du sillon latéral',['À la place du thalamus','Dans la moelle épinière','À l’intérieur de la rétine'],'L’insula est du cortex enfoui, recouvert par des régions voisines.'),
q('ventricles','c1','c1-tissus','Que contiennent les ventricules cérébraux ?','Du liquide céphalorachidien',['Uniquement des axones moteurs','La substance noire','De l’air à l’état normal'],'Les ventricules sont des cavités du système de circulation du LCR.'),
q('dlpfc','c2','c2-attention','Le préfrontal dorsolatéral contribue notamment…','À la mémoire de travail et au contrôle attentionnel',['À lui seul à toute l’inhibition','Uniquement à la contraction des muscles','À transformer la lumière dans la rétine'],'Le DLPFC contribue au contrôle dans un réseau. D’autres régions participent à l’inhibition.'),
q('dmn','c2','c2-attention','Le réseau du mode par défaut participe…','Aux souvenirs et aux pensées orientées vers l’intérieur',['Seulement aux pensées pathologiques','À la fabrication de myéline','Uniquement à l’audition primaire'],'Le DMN a des fonctions normales de mémoire, projection et réflexion sur soi ; ce n’est pas seulement la rumination.'),
q('neglect','c2','c2-espace-langage','L’héminégligence est surtout un trouble…','De l’attention et de la représentation spatiale',['Du cristallin','De la contraction d’un muscle oculaire','Identique à toute perte du champ visuel'],'Une lésion de réseaux droits peut provoquer une négligence gauche ; ce n’est pas une simple déficience visuelle.'),
q('broca','c2','c2-espace-langage','Quel repère classique est lié à la production du langage ?','La région de Broca',['Le cervelet seul','La région de V1','L’hypophyse'],'Broca est un repère frontal du réseau du langage. Production et compréhension mobilisent plusieurs régions.'),
q('wernicke','c2','c2-espace-langage','Quel repère classique est lié à la compréhension du langage ?','La région de Wernicke',['Le noyau sous-thalamique','La rétine','La moelle épinière'],'Wernicke est un repère temporal classique, mais ses limites et le réseau de compréhension sont plus complexes.'),
q('hippocampus','c2','c2-memoire','L’hippocampe contribue particulièrement…','À former de nouveaux souvenirs déclaratifs',['À stocker seul toutes les mémoires','À produire toutes les émotions négatives','À sécréter les hormones hypophysaires'],'Il contribue aux nouveaux souvenirs et à leur contexte ; la mémoire est distribuée et comprend des systèmes différents.'),
q('hm','c2','c2-memoire','Quelle description de l’opération de H.M. est exacte ?','Résection temporale médiale bilatérale avec tissu hippocampique résiduel',['Retrait intégral des deux hippocampes et d’eux seuls','Ablation du cervelet','Résection isolée de M1'],'La résection touchait une partie des hippocampes et des structures voisines. Du tissu hippocampique restait présent.'),
q('amygdala','c2','c2-memoire','Quelle formulation décrit le mieux l’amygdale ?','Elle contribue à apprendre la valeur émotionnelle, positive ou négative',['Elle ne traite que les émotions négatives','Elle stocke seule tous les souvenirs','Elle remplace le thalamus pour tous les sens'],'La menace est un exemple important, mais des populations et circuits amygdaliens participent aussi à des associations positives.'),
q('thalamus','c2','c2-boucles','Le thalamus est…','Un ensemble de plusieurs noyaux de chaque côté',['Seulement deux noyaux uniques','Un des quatre lobes de surface','Une partie du cervelet'],'Les deux masses thalamiques regroupent plusieurs noyaux avec des connexions différentes.'),
q('basal','c2','c2-boucles','Les ganglions de la base contribuent notamment…','À la sélection d’actions et à l’apprentissage d’habitudes',['Uniquement à entendre un son','À produire le LCR','À relier directement les deux yeux'],'Ils participent à des boucles motrices, cognitives et motivationnelles ; « automatismes » n’épuise pas leurs fonctions.'),
q('parkinson','c2','c2-boucles','Quelle modification est majeure dans la maladie de Parkinson ?','Perte de neurones dopaminergiques de la substance noire',['Ablation systématique du thalamus','Disparition de tous les neurones du cortex','Augmentation obligatoire de la vision'],'La perte de neurones dopaminergiques perturbe les circuits des ganglions de la base.'),
q('hypothalamus','c2','c2-homeostasie','Quelle structure participe à la faim, la soif et la régulation hormonale ?','L’hypothalamus',['Le gyrus précentral','V1','Le nerf auditif'],'L’hypothalamus régule l’équilibre interne, notamment en relation avec l’hypophyse.'),
q('parasympathetic','c2','c2-homeostasie','Le parasympathique…','Contribue en permanence à des régulations autonomes',['Ne fonctionne qu’après un danger','Est le cortex moteur secondaire','Ne participe jamais à la digestion'],'Les deux branches autonomes ont une activité continue et des effets dépendant de l’organe.'),
q('cerebellum','c2','c2-coordination','Quel repère contribue à la coordination et à l’adaptation des gestes ?','Le cervelet',['L’hypophyse','La rétine','Le corps calleux seul'],'Le cervelet exploite des commandes et des retours sensoriels pour coordonner et adapter l’action.'),
q('brainstem','c2','c2-eveil','Quels sont les trois étages du tronc cérébral ?','Mésencéphale, pont, bulbe',['Frontal, temporal, pariétal','Hippocampe, amygdale, insula','Caudé, putamen, pallidum'],'Le tronc est distinct du cervelet et se prolonge vers la moelle.'),
q('locked','c2','c2-eveil','Dans le locked-in syndrome classique…','La conscience peut être préservée malgré une paralysie majeure',['L’immobilité prouve un coma','La parole est toujours normale','Seul le cortex visuel est concerné'],'Une atteinte du pont ventral peut empêcher la réponse motrice tout en préservant la conscience.'),
q('td-myelin','td',null,'Quelle cellule myélinise des axones dans le système nerveux central ?','L’oligodendrocyte',['La cellule de Schwann','La microglie','Le globule rouge'],'L’oligodendrocyte myélinise dans le SNC ; la cellule de Schwann remplit ce rôle dans le système nerveux périphérique.'),
q('td-initial','td',null,'Où débute généralement le potentiel d’action d’un neurone ?','Au segment initial de l’axone',['Dans chaque bouton synaptique simultanément','Dans le capillaire','Dans le noyau du soma'],'Le segment initial est spécialisé pour le déclenchement du potentiel d’action au seuil.'),
q('td-microglia','td',null,'Quelle cellule participe aux réponses immunitaires du tissu nerveux ?','La microglie',['La myéline','Le bouton synaptique','L’axone'],'La microglie assure des fonctions de surveillance et de réponse immunitaire.'),
q('td-nodes','td',null,'Un nœud de Ranvier correspond…','À une interruption entre deux segments de myéline',['À un deuxième noyau dans l’axone','À un astrocyte','À une synapse entre deux capillaires'],'Le potentiel d’action est régénéré au niveau des nœuds lors de la conduction saltatoire.')
];
CONCEPT_QUESTIONS.push(...NEURON_QUESTIONS);
CONCEPT_QUESTIONS.push(...ANATOMY_QUESTIONS);
CONCEPT_QUESTIONS.push(...SYNAPSE_QUESTIONS);
for(const q of CONCEPT_QUESTIONS.filter(q=>q.scope==='td'))q.scopes=['c3'];
export const DIAGRAM_QUESTIONS=FIGURES.flatMap(f=>f.parts.map((p,i)=>({id:`figure-${f.id}-${i}`,scope:f.scope,scopes:f.scopes,kind:'diagrams',figure:f.id,part:i,prompt:`Sur ce schéma, que désigne le repère ${i+1} ?`,correct:p.label,options:[p.label,...f.parts.filter(x=>x!==p).map(x=>x.label).slice(0,3)],explanation:p.explain})));
export const QUESTIONS=[...CONCEPT_QUESTIONS,...DIAGRAM_QUESTIONS];
export const matchesScope=(item,scope)=>scope==='all'||item.scope===scope||Boolean(item.scopes?.includes(scope));
export function shuffle(items,random=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function selectQuestions({scope='all',kind='mix',figure,chapter,ids,limit=10}={},random=Math.random){
 const candidates=QUESTIONS.filter(q=>matchesScope(q,scope)&&(kind==='mix'||q.kind===kind)&&(!figure||q.figure===figure)&&(!chapter||q.chapter===chapter)&&(!ids||ids.includes(q.id)));
 return shuffle(candidates,random).slice(0,limit).map(q=>({...q,options:shuffle(q.options,random)}));
}
export function gradeAnswer(question,answer){if(!question.options.includes(answer))throw new Error('Réponse inconnue');return answer===question.correct;}
